// Some portions generated by Claude
import type {EdgeCurve, PointerPosition} from './graph-types.ts';
import type {Bounds} from './spatial-grid.ts';

type Quadratic = Pick<EdgeCurve, 'start' | 'control' | 'end'>;
const inside = (p: PointerPosition, b: Bounds) => p.x >= b.minX && p.x <= b.maxX && p.y >= b.minY && p.y <= b.maxY;

/** Liang–Barsky clipping, including tangencies and zero-length segments. */
export function segmentIntersectsBounds(a: PointerPosition, b: PointerPosition, box: Bounds): boolean {
  let low = 0, high = 1;
  for (const axis of ['x', 'y'] as const) {
    const delta = b[axis] - a[axis], min = axis === 'x' ? box.minX : box.minY, max = axis === 'x' ? box.maxX : box.maxY;
    if (delta === 0) {if (a[axis] < min || a[axis] > max) return false; continue;}
    const t0 = (min - a[axis]) / delta, t1 = (max - a[axis]) / delta;
    low = Math.max(low, Math.min(t0, t1)); high = Math.min(high, Math.max(t0, t1));
    if (low > high) return false;
  }
  return true;
}

const evaluate = (start: number, control: number, end: number, t: number) =>
  start + t * (2 * (control - start) + t * ((end - control) - (control - start)));

/** Tight bounds, unlike a control-point hull or incomplete samples. */
export function quadraticBounds(curve: Quadratic): Bounds {
  const extent = (axis: 'x' | 'y') => {
    const s = curve.start[axis], c = curve.control[axis], e = curve.end[axis];
    let min = Math.min(s, e), max = Math.max(s, e);
    const a = (e - c) - (c - s), t = a === 0 ? -1 : (s - c) / a;
    if (t > 0 && t < 1) {const v = evaluate(s, c, e, t); min = Math.min(min, v); max = Math.max(max, v);}
    return [min, max];
  };
  const x = extent('x'), y = extent('y');
  return {minX: x[0], minY: y[0], maxX: x[1], maxY: y[1]};
}

/** Analytic rectangle-boundary intersections across the ENTIRE Bézier.
 * A finite sample set cannot establish obstacle avoidance for long edges.
 * Differences keep coefficients stable when the whole map is translated.
 */
export function quadraticIntersectsBounds(curve: Quadratic, box: Bounds): boolean {
  if (inside(curve.start, box) || inside(curve.end, box)) return true;
  for (const axis of ['x', 'y'] as const) {
    const other = axis === 'x' ? 'y' : 'x';
    const s = curve.start[axis], c = curve.control[axis], e = curve.end[axis];
    const a = (e - c) - (c - s), b = 2 * (c - s);
    const min = axis === 'x' ? box.minY : box.minX, max = axis === 'x' ? box.maxY : box.maxX;
    const hits = (t: number) => {
      if (t < 0 || t > 1 || !Number.isFinite(t)) return false;
      const v = evaluate(curve.start[other], curve.control[other], curve.end[other], t);
      return v >= min && v <= max;
    };
    for (const boundary of axis === 'x' ? [box.minX, box.maxX] : [box.minY, box.maxY]) {
      const d = s - boundary;
      if (Math.abs(a) < 1e-12 * Math.max(1, Math.abs(b))) {if (b !== 0 && hits(-d / b)) return true; continue;}
      const discriminant = b * b - 4 * a * d;
      if (discriminant < 0) continue;
      const q = -.5 * (b + (b < 0 ? -1 : 1) * Math.sqrt(discriminant));
      if (q === 0 ? hits(-b / (2 * a)) : hits(q / a) || hits(d / q)) return true;
    }
  }
  return false;
}
